<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#17232d}h1{color:#012642}table{width:100%;border-collapse:collapse}td{padding:12px;border-bottom:1px solid #ddd}td:last-child{text-align:right}footer{margin-top:40px;border-top:4px solid #f6c620;padding-top:20px}</style></head><body>
<img src="{{ public_path('assets/lte/cargo-logo-email.png') }}" width="180" height="72" alt="New World Cargo"><h1>Payment receipt</h1><h2>{{ $receipt->receipt_number }}</h2>
<p>{{ json_decode($document->customer_snapshot,true)['name'] }}</p><p>Invoice: {{ $document->number }}</p>
<table><tr><td>Date received</td><td>{{ $receipt->paid_on }}</td></tr><tr><td>Method</td><td>{{ ucfirst(str_replace('_',' ',$receipt->method)) }}</td></tr><tr><td>Reference</td><td>{{ $receipt->reference }}</td></tr><tr><td><strong>Amount received</strong></td><td><strong>{{ $receipt->currency }} {{ number_format($receipt->amount_minor/100,2) }}</strong></td></tr><tr><td>Balance after this payment</td><td>{{ $receipt->currency }} {{ number_format($receipt->balance_after_minor/100,2) }}</td></tr></table><footer>Thank you for your payment.<br>New World Cargo</footer></body></html>
